import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { drizzle, type NodeSQLiteDatabase } from 'drizzle-orm/node-sqlite';
import { migrate } from 'drizzle-orm/node-sqlite/migrator';

export type Db = NodeSQLiteDatabase & { $client: DatabaseSync };

/** Folder with the SQL migrations generated by drizzle-kit (`pnpm db:generate`). */
export const MIGRATIONS_DIR = path.resolve(import.meta.dirname, '..', 'drizzle');

export interface OpenOptions {
  /** database file, or ':memory:' */
  file: string;
  /** override when the migrations are shipped somewhere else (the desktop bundle) */
  migrationsFolder?: string;
}

/**
 * Open (creating if needed) the app database and bring its schema up to date.
 * Uses Node's built-in SQLite, so there is no native module to rebuild for Electron.
 */
export function openDatabase({ file, migrationsFolder = MIGRATIONS_DIR }: OpenOptions): Db {
  if (file !== ':memory:') fs.mkdirSync(path.dirname(file), { recursive: true });
  const client = new DatabaseSync(file);
  client.exec('PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000; PRAGMA synchronous = NORMAL;');
  const db = drizzle({ client }) as Db;
  migrate(db, { migrationsFolder });
  return db;
}

export function closeDatabase(db: Db): void {
  if (db.$client.isOpen) db.$client.close();
}
